1	// contractlab —— 可热更新的本地接口场景服务
2	//
3	// 运行环境：Node.js 24（内置 TypeScript 类型擦除，可直接 `node app.ts`），
4	// 无任何外部运行依赖。
5	//
6	// 行为约定（详见 README.md）：
7	// - 业务接口由“方法 + 绝对路径”唯一标识，查询串不参与匹配，不支持路径模板；
8	// - 请求被完整接收后，才按当前配置匹配接口并同步“预留”响应序列的下一项，
9	//   序列耗尽后持续返回末项；预留之后客户端断开，仍计为一次消费；
10	// - POST /__contractlab/reload 重新读取同一配置文件：新配置全部有效时才
11	//   原子替换全部接口、重置全部序列并递增版本号；失败时现状不变；
12	// - 在途请求持有预留时的旧响应快照（状态码/响应头/正文/延迟/版本），
13	//   完成时不会推进新序列；
14	// - POST 接口可附加可选的 requestBody 正文结构规则：请求完整接收后先校验
15	//   媒体类型与 JSON 结构，不符时返回 400 差异报告，不发送场景响应、不消费序列；
16	//   校验通过才按“完整接收”顺序预留响应项。任意规则节点可附布尔 nullable：
17	//   true 在原接受集合上加入 null（必填字段仍不得缺失，空正文不等于 null）；
18	//   标量节点可附非空 enum 候选数组：接受集合为“类型及可空集合”与枚举集合的
19	//   交集（可空不越过枚举；object/array 节点禁止 enum）。
20	// - 已声明 requestBody 的 POST 接口还可配置有序响应分支 branches：每支含接口内
21	//   唯一非空标识 id、非空等值条件集合 when（RFC 6901 指针 -> 字符串/有限数字/
22	//   布尔/null，支持根、对象自有字段与数组下标，保留空字段名、__proto__ 与 ~0/~1
23	//   转义）与非空响应序列 responses；接口原 responses 成为无分支命中时的兜底序列。
24	//   请求通过全部正文校验后按同一配置快照选择：指针取值不存在或无法遍历即不命中
25	//   （缺失不同于 null、不做类型转换、0 与 -0 相等），全部条件满足才命中该支；
26	//   多支命中取第一支，无命中取兜底。各分支与兜底独立计数，不改写请求字节。
27	// - 管理入口 GET /__contractlab/requests 查询本次进程内的请求记录（一致快照、
28	//   不推进序列），POST /__contractlab/requests/clear 清空记录；记录只存在内存中，
29	//   管理范围（/__contractlab 本身及 /__contractlab/ 前缀）的请求一律不记录。
30	// - compare 子命令：离线比较旧、新两份场景文件，判断沿用旧接口约定的客户端
31	//   是否仍能调用新版；报告写 stdout，不启动监听、不修改文件。
32	// - import 子命令：读取本地 OpenAPI 3.0 JSON 与现有场景配置，按“方法 + 字面
33	//   路径”选择文档操作，仅用操作 requestBody 转换出的正文规则替换各接口的
34	//   requestBody（保留接口顺序与 responses），新场景 JSON 写 stdout。
35	// - verify 子命令：离线批量请求校验。读取 GET /__contractlab/requests 的完整
36	//   JSON 快照与一份场景配置，按输入顺序保留原编号逐条重新判定（仅依据记录中的
37	//   原始请求重新计算，不信任原版本、匹配/校验结论、计划响应与发送状态）；
38	//   报告写 stdout，不监听、不发送请求、不修改文件。
39	// - replay 子命令：本机请求重放与响应差异报告。读取同一份请求记录快照，
40	//   按输入顺序把每条记录的原始请求逐条重放到 127.0.0.1 的指定端口
41	//   （每条只尝试一次、不跟随重定向、每条有覆盖完整收发的总超时），
42	//   仅比较实际响应的状态码与正文和记录中的计划响应；可选 --strategy
43	//   比较策略按“方法 + 字面路径”为接口选择正文 JSON 语义比较（忽略键序、
44	//   排版与指定的 RFC 6901 忽略指针；可为互不嵌套的数组位置指定元素自有
45	//   字段作业务键对齐，按键配对后顺序不影响结论），未选中的接口仍按
46	//   原始字节比较；
47	//   报告写 stdout，不监听、不修改文件。
48	
49	import http from 'node:http';
50	import { readFile } from 'node:fs/promises';
51	import path from 'node:path';
52	
53	const APP_NAME = 'contractlab';
54	
55	// 管理入口（保留前缀，业务接口不得使用）
56	const ADMIN_PREFIX = '/__contractlab/';
57	const ADMIN_BASE = '/__contractlab';
58	const HEALTH_PATH = '/__contractlab/health';
59	const RELOAD_PATH = '/__contractlab/reload';
60	const REQUESTS_PATH = '/__contractlab/requests';
61	const REQUESTS_CLEAR_PATH = '/__contractlab/requests/clear';
62	
63	// 每个业务响应都携带当前配置版本
64	const VERSION_HEADER = 'X-Contractlab-Version';
65	
66	// 请求体上限（本机工具的防误操作保护，超出直接 413，不触碰任何序列）
67	const MAX_BODY_BYTES = 100 * 1024 * 1024;
68	
69	// 由服务器管理、业务配置不得覆盖的“传输头”（大小写不敏感）
70	const BLOCKED_HEADERS = new Set([
71	  'connection',
72	  'keep-alive',
73	  'content-length',
74	  'transfer-encoding',
75	]);
76	
77	// RFC 7230 token：合法的 HTTP 头名称字符
78	const HEADER_NAME_RE = /^[!#$%&'*+\-.^_`|~0-9A-Za-z]+$/;
79	
80	type HttpMethod = 'GET' | 'POST';
81	
82	// ---------------------------------------------------------------------------
83	// 请求正文结构规则（endpoints[].requestBody，仅 POST）
84	// ---------------------------------------------------------------------------
85	//
86	// 规则格式（JSON 对象，未知字段一律拒绝）：
87	//   { "type": "object", "fields": { "<名>": <字段规则>, ... }, "additionalProperties": false }
88	//   { "type": "array", "items": <规则> }
89	//   { "type": "string" | "number" | "integer" | "boolean" | "null" }
90	// 任意规则节点（根、字段、数组元素）可附布尔 "nullable"：省略或 false 行为不变，
91	// true 在原接受集合上加入 null（type:null 本就只接受 null）。必填字段即使可空也
92	// 不能缺失；null 被接受时不产生子节点差异，非 null 值仍须通过全部原约束。
93	// 标量节点（string/number/integer/boolean/null）可附非空 "enum" 候选数组：
94	// 每项须符合节点类型与可空约定（null 项要求 nullable:true 或 type:null），
95	// 顺序与重复值不影响语义（数字按数值相等，0 与 -0 等价，不做类型转换）；
96	// 有 enum 时接受集合为“类型及可空集合”与枚举集合的交集（可空不越过枚举）。
97	// object / array 节点禁止 enum。
98	// 字段规则 = 任意规则 + 可选 "required": true（缺省为可缺省）；
99	// object 的 fields / additionalProperties 可省略（默认无字段声明、拒绝未声明字段）；
100	// array 必须声明 items。
101	
102	type ScalarKind = 'string' | 'number' | 'integer' | 'boolean' | 'null';
103	
104	// 枚举候选值：标量字面量（含 null，仅当节点可空或 type:null 时允许）
105	type EnumValue = string | number | boolean | null;
106	
107	type BodyRule =
108	  | {
109	      readonly kind: 'object';
110	      readonly fields: ReadonlyMap<string, FieldRule>;
111	      readonly additionalProperties: boolean;
112	      readonly nullable: boolean;
113	    }
114	  | { readonly kind: 'array'; readonly items: BodyRule; readonly nullable: boolean }
115	  | {
116	      readonly kind: ScalarKind;
117	      readonly nullable: boolean;
118	      // 非空候选数组（已按数值相等去重）；undefined 表示无枚举限制
119	      readonly enum: readonly EnumValue[] | undefined;
120	    };
121	
122	interface FieldRule {
123	  readonly rule: BodyRule;
124	  readonly required: boolean;
125	}
126	
127	// ---------------------------------------------------------------------------
128	// 按请求正文值选择的响应分支（endpoints[].branches，仅 POST 且声明 requestBody）
129	// ---------------------------------------------------------------------------
130	//
131	// 每个分支：
132	//   { "id": "<接口内唯一非空标识>",
133	//     "when": { "<RFC 6901 指针>": <等值条件值>, ... },   // 非空对象、至少一条
134	//     "responses": [ <非空响应序列> ] }
135	// 条件值只能是字符串、有限数字、布尔或 null；指针支持根（""）、对象自有字段
136	// （含空字段名与 "__proto__"）与数组下标，遵循 ~0/~1 转义。分支有序：全部条件
137	// 满足即命中该支，多支命中取第一支，均不命中时使用接口 responses 兜底序列。
138	
139	type BranchConditionValue = string | number | boolean | null;
140	
141	interface BranchCondition {
142	  // 原始指针串（RFC 6901），用于记录与错误定位
143	  readonly pointer: string;
144	  // 已解码的指针段（根指针为空数组）
145	  readonly segments: readonly string[];
146	  readonly value: BranchConditionValue;
147	}
148	
149	interface BranchSpec {
150	  readonly id: string;
151	  readonly conditions: readonly BranchCondition[];
152	  readonly responses: readonly ResponseSpec[];
153	}
154	
155	interface ResponseSpec {
156	  readonly status: number;
157	  readonly headers: { readonly [name: string]: string };
158	  readonly body: string;
159	  readonly delay: number;
160	}
161	
162	interface EndpointSpec {
163	  readonly method: HttpMethod;
164	  readonly path: string;
165	  // 兜底响应序列（无分支命中时使用）
166	  readonly responses: readonly ResponseSpec[];
167	  readonly bodyRule: BodyRule | undefined;
168	  // 有序分支；仅当 bodyRule 存在时非空
169	  readonly branches: readonly BranchSpec[];
170	}
171	
172	interface LiveBranch {
173	  readonly id: string;
174	  readonly conditions: readonly BranchCondition[];
175	  readonly responses: readonly ResponseSpec[];
176	  // 下一个待预留位置；到达末项后停在末项（持续复用）
177	  cursor: number;
178	}
179	
180	interface LiveEndpoint {
181	  readonly key: string;
182	  // 兜底序列
183	  readonly responses: readonly ResponseSpec[];
184	  readonly bodyRule: BodyRule | undefined;
185	  readonly branches: readonly LiveBranch[];
186	  // 兜底序列的下一个待预留位置
187	  cursor: number;
188	}
189	
190	interface LiveState {
191	  readonly version: number;
192	  readonly endpoints: ReadonlyMap<string, LiveEndpoint>;
193	}
194	
195	interface ReloadResult {
196	  ok: boolean;
197	  version: number;
198	  error?: string;
199	}
200	
201	class ConfigError extends Error {
202	  constructor(message: string) {
203	    super(message);
204	    this.name = 'ConfigError';
205	  }
206	}
207	
208	// ---------------------------------------------------------------------------
209	// 配置校验
210	// ---------------------------------------------------------------------------
211	
212	function isPlainObject(value: unknown): value is Record<string, unknown> {
213	  return typeof value === 'object' && value !== null && !Array.isArray(value);
214	}
215	
216	function validatePath(p: string, where: string): void {
217	  if (p.length === 0 || p[0] !== '/') {
218	    throw new ConfigError(`${where}.path 必须是以 "/" 开头的绝对路径，收到 "${p}"`);
219	  }
220	  if (p.length > 4096) {
221	    throw new ConfigError(`${where}.path 过长（最多 4096 字符）`);
222	  }
223	  for (const ch of p) {
224	    const code = ch.charCodeAt(0);
225	    if (ch === '?' || ch === '#' || ch === '{' || ch === '}') {
226	      throw new ConfigError(
227	        `${where}.path "${p}" 含有非法字符 "${ch}"：查询串不参与匹配，且不支持路径模板`,
228	      );
229	    }
230	    if (code <= 0x1f || code === 0x7f || code === 0x20) {
231	      throw new ConfigError(`${where}.path "${p}" 不得包含空白或控制字符`);
232	    }
233	  }
234	}
235	
236	function validateResponse(raw: unknown, where: string): ResponseSpec {
237	  if (!isPlainObject(raw)) {
238	    throw new ConfigError(`${where} 必须是对象`);
239	  }
240	  for (const key of Object.keys(raw)) {
241	    if (key !== 'status' && key !== 'headers' && key !== 'body' && key !== 'delay') {
242	      throw new ConfigError(`${where} 含未知字段 "${key}"`);
243	    }
244	  }
245	
246	  const { status, headers, body, delay } = raw;
247	
248	  if (!Number.isInteger(status) || status < 200 || status > 599) {
249	    throw new ConfigError(`${where}.status 必须是 200 至 599 之间的整数，收到 ${JSON.stringify(status)}`);
250	  }
251	
252	  if (!isPlainObject(headers)) {
253	    throw new ConfigError(`${where}.headers 必须是字符串键值对象`);
254	  }
255	  // 无原型对象：名为 "__proto__" 的头也按自有字段保留，不被原型 setter 吞掉
256	  const cleanHeaders: { [name: string]: string } = Object.create(null);
257	  const seenNames = new Set<string>();
258	  for (const [name, value] of Object.entries(headers)) {
259	    const whereHeader = `${where}.headers["${name}"]`;
260	    if (!HEADER_NAME_RE.test(name)) {
261	      throw new ConfigError(`${whereHeader} 不是合法的 HTTP 响应头名称`);
262	    }
263	    const lower = name.toLowerCase();
264	    if (BLOCKED_HEADERS.has(lower)) {
265	      throw new ConfigError(`${whereHeader} 属于服务器管理的传输头，不允许在配置中设置`);
266	    }
267	    if (seenNames.has(lower)) {
268	      throw new ConfigError(`${whereHeader} 与同序列内另一个响应头仅大小写不同，视为重复`);
269	    }
270	    if (typeof value !== 'string') {
271	      throw new ConfigError(`${whereHeader} 的值必须是字符串`);
272	    }
273	    for (let i = 0; i < value.length; i += 1) {
274	      const code = value.charCodeAt(i);
275	      // 允许水平制表符(0x09)；拒绝换行及其余控制字符；
276	      // Node 的 HTTP 头值只支持 Latin-1（0x80-0xFF），更高码位发送时会抛错
277	      if ((code <= 0x1f && code !== 0x09) || code === 0x7f || code > 0xff) {
278	        throw new ConfigError(
279	          `${whereHeader} 的值不得包含换行或其他控制字符，且只能使用 Latin-1 字符`,
280	        );
281	      }
282	    }
283	    seenNames.add(lower);
284	    cleanHeaders[name] = value;
285	  }
286	
287	  if (typeof body !== 'string') {
288	    throw new ConfigError(`${where}.body 必须是文本字符串`);
289	  }
290	  if ((status === 204 || status === 304) && body !== '') {
291	    throw new ConfigError(`${where}.body 状态码为 ${status} 时正文必须为空字符串`);
292	  }
293	
294	  if (!Number.isInteger(delay) || delay < 0 || delay > 60000) {
295	    throw new ConfigError(`${where}.delay 必须是 0 至 60000 之间的整数毫秒数，收到 ${JSON.stringify(delay)}`);
296	  }
297	
298	  return { status, headers: cleanHeaders, body, delay };
299	}
300	
301	const SCALAR_KINDS: ReadonlySet<string> = new Set([
302	  'string',
303	  'number',
304	  'integer',
305	  'boolean',
306	  'null',
307	]);
308	
309	// 枚举项是否满足节点类型（不做类型转换；number 限有限数字、integer 限整数）
310	function enumItemConforms(kind: ScalarKind, item: unknown): boolean {
311	  switch (kind) {
312	    case 'string':
313	      return typeof item === 'string';
314	    case 'number':
315	      return typeof item === 'number' && Number.isFinite(item);
316	    case 'integer':
317	      return Number.isInteger(item);
318	    case 'boolean':
319	      return typeof item === 'boolean';
320	    case 'null':
321	      return item === null;
322	  }
323	}
324	
325	// 校验并规范化枚举候选（场景配置与 OpenAPI 导入共用语义）：非空数组、逐项符合
326	// 节点类型与可空约定（null 项要求 nullable:true 或 type:null）、按数值相等去重
327	// （0 与 -0 等价；顺序与重复值不影响语义）。失败返回可定位的 where 与原因。
328	function enumValuesOrError(
329	  enumRaw: unknown,
330	  kind: ScalarKind,
331	  nullable: boolean,
332	  where: string,
333	): { errorWhere: string; message: string } | { values: EnumValue[] } {
334	  if (!Array.isArray(enumRaw) || enumRaw.length === 0) {
335	    return { errorWhere: where, message: '必须是非空数组（至少一个候选值）' };
336	  }
337	  // Set 按 SameValueZero 去重：0 与 -0 视为同一候选
338	  const seen = new Set<unknown>();
339	  const values: EnumValue[] = [];
340	  for (let i = 0; i < enumRaw.length; i += 1) {
341	    const item = enumRaw[i];
342	    const itemWhere = `${where}[${i}]`;
343	    if (item === null) {
344	      if (!nullable && kind !== 'null') {
345	        return {
346	          errorWhere: itemWhere,
347	          message: '为 null：接受 null 要求节点为 nullable:true 或 type:"null"',
348	        };
349	      }
350	    } else if (!enumItemConforms(kind, item)) {
351	      return {
352	        errorWhere: itemWhere,
353	        message: `必须是 ${kind}（与节点类型一致，不做类型转换），收到 ${JSON.stringify(item)}`,
354	      };
355	    }
356	    if (!seen.has(item)) {
357	      seen.add(item);
358	      values.push(item as EnumValue);
359	    }
360	  }
361	  return { values };
362	}
363	
364	function validateBodyRule(raw: unknown, where: string): BodyRule {
365	  if (!isPlainObject(raw)) {
366	    throw new ConfigError(`${where} 必须是对象（含 "type" 字段）`);
367	  }
368	
369	  const type = raw.type;
370	  const allowed = new Set(['type', 'nullable']);
371	  if (type === 'object') {
372	    allowed.add('fields');
373	    allowed.add('additionalProperties');
374	  } else if (type === 'array') {
375	    allowed.add('items');
376	  } else if (!SCALAR_KINDS.has(type as string)) {
377	    throw new ConfigError(
378	      `${where}.type 必须是 "object" | "array" | "string" | "number" | "integer" | "boolean" | "null"，收到 ${JSON.stringify(type)}`,
379	    );
380	  } else {
381	    // enum 仅允许在标量节点上；object / array 节点声明 enum 按未知字段拒绝
382	    allowed.add('enum');
383	  }
384	  for (const key of Object.keys(raw)) {
385	    if (!allowed.has(key)) {
386	      throw new ConfigError(`${where} 含未知字段 "${key}"`);
387	    }
388	  }
389	
390	  // 任意规则节点可附布尔 nullable：省略或 false 不变，true 在原接受集合上加入 null
391	  const nullableRaw = raw.nullable;
392	  if (nullableRaw !== undefined && typeof nullableRaw !== 'boolean') {
393	    throw new ConfigError(`${where}.nullable 必须是布尔值，收到 ${JSON.stringify(nullableRaw)}`);
394	  }
395	  const nullable = nullableRaw === true;
396	
397	  // 标量节点可附非空 enum：每项须符合节点类型与可空约定；有枚举时接受集合为
398	  // “类型及可空集合”与枚举集合的交集（可空不越过枚举，null 须列入枚举才被接受）
399	  let enumValues: readonly EnumValue[] | undefined;
400	  if (raw.enum !== undefined) {
401	    const result = enumValuesOrError(raw.enum, type as ScalarKind, nullable, `${where}.enum`);
402	    if ('errorWhere' in result) {
403	      throw new ConfigError(`${result.errorWhere} ${result.message}`);
404	    }
405	    enumValues = result.values;
406	  }
407	
408	  if (type === 'object') {
409	    const fieldsRaw = raw.fields;
410	    const fields = new Map<string, FieldRule>();
411	    if (fieldsRaw !== undefined) {
412	      if (!isPlainObject(fieldsRaw)) {
413	        throw new ConfigError(`${where}.fields 必须是对象（字段名 → 字段规则）`);
414	      }
415	      for (const [name, fieldRaw] of Object.entries(fieldsRaw)) {
416	        fields.set(name, validateFieldRule(fieldRaw, `${where}.fields[${JSON.stringify(name)}]`));
417	      }
418	    }
419	    const additional = raw.additionalProperties;
420	    if (additional !== undefined && typeof additional !== 'boolean') {
421	      throw new ConfigError(`${where}.additionalProperties 必须是布尔值`);
422	    }
423	    // 未声明字段默认拒绝
424	    return { kind: 'object', fields, additionalProperties: additional === true, nullable };
425	  }
426	
427	  if (type === 'array') {
428	    if (raw.items === undefined) {
429	      throw new ConfigError(`${where}.items 数组规则必须声明元素规则`);
430	    }
431	    return { kind: 'array', items: validateBodyRule(raw.items, `${where}.items`), nullable };
432	  }
433	
434	  return { kind: type as ScalarKind, nullable, enum: enumValues };
435	}
436	
437	// 字段规则 = 任意规则 + 可选 "required"（仅允许出现在 object 的 fields 条目中）
438	function validateFieldRule(raw: unknown, where: string): FieldRule {
439	  if (!isPlainObject(raw)) {
440	    throw new ConfigError(`${where} 必须是对象（含 "type" 字段）`);
441	  }
442	  let required = false;
443	  // 无原型对象：未知规则键 "__proto__" 必须作为自有字段保留下来，
444	  // 交由 validateBodyRule 拒绝；普通对象字面量会在复制时被原型 setter 吞掉
445	  const rest: Record<string, unknown> = Object.create(null);
446	  for (const [key, value] of Object.entries(raw)) {
447	    if (key === 'required') {
448	      if (typeof value !== 'boolean') {
449	        throw new ConfigError(`${where}.required 必须是布尔值`);
450	      }
451	      required = value;
452	    } else {
453	      rest[key] = value;
454	    }
455	  }
456	  return { rule: validateBodyRule(rest, where), required };
457	}
458	
459	// RFC 6901 JSON Pointer 语法解析："" 表示根（零段）；否则必须以 "/" 开头，
460	// 按 "/" 分段并反转义（~1 -> "/"，~0 -> "~"，先处理 ~1 以免二次转义）。
461	// 段内出现不以 0/1 收尾的 "~" 属非法指针。这里只判定语法；段能否在具体 JSON
462	// 值上遍历（对象自有字段、数组下标）由运行时选择逻辑判定。
463	// label 用于错误信息中对指针用途的称呼（分支条件键 / 忽略指针）。
464	function parseJsonPointer(raw: unknown, where: string, label = '条件键'): string[] {
465	  if (typeof raw !== 'string') {
466	    throw new ConfigError(`${where} 的${label}必须是 RFC 6901 指针字符串，收到 ${JSON.stringify(raw)}`);
467	  }
468	  if (raw === '') {
469	    return [];
470	  }
471	  if (raw[0] !== '/') {
472	    throw new ConfigError(
473	      `${where} 的指针 ${JSON.stringify(raw)} 非法：非根指针必须以 "/" 开头（根指针为 ""）`,
474	    );
475	  }
476	  return raw.slice(1).split('/').map((segment, i) => {
477	    let out = '';
478	    for (let j = 0; j < segment.length; j += 1) {
479	      const ch = segment[j];
480	      if (ch === '~') {
481	        const next = segment[j + 1];
482	        if (next === '0') {
483	          out += '~';
484	          j += 1;
485	        } else if (next === '1') {
486	          out += '/';
487	          j += 1;
488	        } else {
489	          throw new ConfigError(
490	            `${where} 的指针 ${JSON.stringify(raw)} 非法：第 ${i} 段含非法转义（仅支持 ~0 与 ~1）`,
491	          );
492	        }
493	      } else {
494	        out += ch;
495	      }
496	    }
497	    return out;
498	  });
499	}
500	
501	// 等值条件值：字符串、有限数字、布尔或 null（不接受 NaN/Infinity、对象、数组）
502	function validateConditionValue(raw: unknown, where: string): BranchConditionValue {
503	  if (raw === null) {
504	    return null;
505	  }
506	  if (typeof raw === 'string' || typeof raw === 'boolean') {
507	    return raw;
508	  }
509	  if (typeof raw === 'number') {
510	    if (!Number.isFinite(raw)) {
511	      throw new ConfigError(
512	        `${where} 的条件值必须是有限数字，收到 ${JSON.stringify(raw)}`,
513	      );
514	    }
515	    return raw;
516	  }
517	  throw new ConfigError(
518	    `${where} 的条件值必须是字符串、有限数字、布尔或 null，收到 ${JSON.stringify(raw)}`,
519	  );
520	}
521	
522	function validateBranch(raw: unknown, endpointWhere: string, index: number, seenIds: Set<string>): BranchSpec {
523	  const where = `${endpointWhere}.branches[${index}]`;
524	  if (!isPlainObject(raw)) {
525	    throw new ConfigError(`${where} 必须是对象`);
526	  }
527	  for (const key of Object.keys(raw)) {
528	    if (key !== 'id' && key !== 'when' && key !== 'responses') {
529	      throw new ConfigError(`${where} 含未知字段 "${key}"`);
530	    }
531	  }
532	
533	  const { id, when, responses } = raw;
534	
535	  if (typeof id !== 'string' || id === '') {
536	    throw new ConfigError(`${where}.id 必须是非空字符串，收到 ${JSON.stringify(id)}`);
537	  }
538	  if (seenIds.has(id as string)) {
539	    throw new ConfigError(`${where}.id ${JSON.stringify(id)} 与同一接口的其他分支标识重复`);
540	  }
541	  seenIds.add(id as string);
542	
543	  if (!isPlainObject(when)) {
544	    throw new ConfigError(`${where}.when 必须是“指针 -> 条件值”的非空对象`);
545	  }
546	  // JSON.parse 以 CreateDataProperty 写入，名为 "__proto__" 的条件键仍是自有字段
547	  const entries = Object.entries(when);
548	  if (entries.length === 0) {
549	    throw new ConfigError(`${where}.when 必须至少包含一条等值条件`);
550	  }
551	  const conditions: BranchCondition[] = entries.map(([pointer, valueRaw]) => {
552	    const condWhere = `${where}.when[${JSON.stringify(pointer)}]`;
553	    const segments = parseJsonPointer(pointer, condWhere);
554	    const value = validateConditionValue(valueRaw, condWhere);
555	    return { pointer, segments, value };
556	  });
557	
558	  if (!Array.isArray(responses) || responses.length === 0) {
559	    throw new ConfigError(`${where}.responses 必须是非空数组`);
560	  }
561	  const cleanResponses = responses.map((item, j) =>
562	    validateResponse(item, `${where}.responses[${j}]`),
563	  );
564	
565	  return { id: id as string, conditions, responses: cleanResponses };
566	}
567	
568	function validateEndpoint(
569	  raw: unknown,
570	  index: number,
571	  seen: Set<string>,
572	): EndpointSpec {
573	  const where = `endpoints[${index}]`;
574	  if (!isPlainObject(raw)) {
575	    throw new ConfigError(`${where} 必须是对象`);
576	  }
577	  for (const key of Object.keys(raw)) {
578	    if (
579	      key !== 'method' &&
580	      key !== 'path' &&
581	      key !== 'responses' &&
582	      key !== 'requestBody' &&
583	      key !== 'branches'
584	    ) {
585	      throw new ConfigError(`${where} 含未知字段 "${key}"`);
586	    }
587	  }
588	
589	  const { method, path: routePath, responses, requestBody, branches: branchesRaw } = raw;
590	
591	  if (method !== 'GET' && method !== 'POST') {
592	    throw new ConfigError(`${where}.method 必须是 "GET" 或 "POST"，收到 ${JSON.stringify(method)}`);
593	  }
594	
595	  if (typeof routePath !== 'string') {
596	    throw new ConfigError(`${where}.path 必须是字符串`);
597	  }
598	  validatePath(routePath, where);
599	  if (routePath === '/__contractlab' || routePath.startsWith(ADMIN_PREFIX)) {
600	    throw new ConfigError(
601	      `${where}.path "${routePath}" 与管理入口冲突：前缀 "${ADMIN_PREFIX}" 为管理接口保留`,
602	    );
603	  }
604	
605	  const key = `${method} ${routePath}`;
606	  if (seen.has(key)) {
607	    throw new ConfigError(`${where} 与其他接口重复（方法 + 路径必须唯一）：${key}`);
608	  }
609	  seen.add(key);
610	
611	  if (!Array.isArray(responses) || responses.length === 0) {
612	    throw new ConfigError(`${where}.responses 必须是非空数组`);
613	  }
614	  const cleanResponses = responses.map((item, j) =>
615	    validateResponse(item, `${where}.responses[${j}]`),
616	  );
617	
618	  let bodyRule: BodyRule | undefined;
619	  if (requestBody !== undefined) {
620	    if (method !== 'POST') {
621	      throw new ConfigError(`${where}.requestBody 仅允许在 POST 接口上声明（GET 接口不允许携带此规则）`);
622	    }
623	    bodyRule = validateBodyRule(requestBody, `${where}.requestBody`);
624	  }
625	
626	  let branches: readonly BranchSpec[] = [];
627	  if (branchesRaw !== undefined) {
628	    // 分支以正文值为条件：GET 接口与未声明 requestBody 的 POST 接口一律禁止
629	    if (method !== 'POST') {
630	      throw new ConfigError(`${where}.branches 仅允许在 POST 接口上声明（GET 接口不允许配置响应分支）`);
631	    }
632	    if (!bodyRule) {
633	      throw new ConfigError(
634	        `${where}.branches 仅允许在声明了 requestBody 的 POST 接口上配置：按正文值选择分支必须先声明正文规则`,
635	      );
636	    }
637	    if (!Array.isArray(branchesRaw) || branchesRaw.length === 0) {
638	      throw new ConfigError(`${where}.branches 必须是非空数组`);
639	    }
640	    const seenIds = new Set<string>();
641	    branches = branchesRaw.map((branch, j) => validateBranch(branch, where, j, seenIds));
642	  }
643	
644	  return { method, path: routePath, responses: cleanResponses, bodyRule, branches };
645	}
646	
647	function validateConfig(raw: unknown): EndpointSpec[] {
648	  if (!isPlainObject(raw)) {
649	    throw new ConfigError('配置顶层必须是 JSON 对象');
650	  }
651	  for (const key of Object.keys(raw)) {
652	    if (key !== 'endpoints') {
653	      throw new ConfigError(`未知顶层字段 "${key}"，仅允许 "endpoints"`);
654	    }
655	  }
656	  const list = raw.endpoints;
657	  if (!Array.isArray(list) || list.length === 0) {
658	    throw new ConfigError('endpoints 必须是至少包含一个接口的数组');
659	  }
660	  const seen = new Set<string>();
661	  return list.map((ep, i) => validateEndpoint(ep, i, seen));
662	}
