687	// 一个可选序列的预留结果：分支命中时为该支序列，否则为接口兜底序列
688	interface ReservedResponse {
689	  readonly position: number;
690	  readonly item: ResponseSpec;
691	  // 命中的分支标识；null 表示兜底
692	  readonly branchId: string | null;
693	  // 选中序列（用于记录 sequenceLength）
694	  readonly sequence: readonly ResponseSpec[];
695	}
696	
697	// 同步预留下一项；同一事件循环内按“完整接收”事件的先后串行调用，天然保序。
698	// 末项之后持续返回末项，不跳项、不复用未到位置的项。
699	// 返回本次消费位置（0 起）与该项；末项复用时位置停在 length-1。
700	function reserveFromSequence(
701	  responses: readonly ResponseSpec[],
702	  cursorRef: { cursor: number },
703	): { position: number; item: ResponseSpec } {
704	  const last = responses.length - 1;
705	  const position = cursorRef.cursor < last ? cursorRef.cursor : last;
706	  if (cursorRef.cursor < last) {
707	    cursorRef.cursor += 1;
708	  }
709	  return { position, item: responses[position] };
710	}
711	
712	// 按 RFC 6901 段在已解析 JSON 值上取值：
713	// - 零段（根指针 ""）返回根值；
714	// - 对象按自有字段（hasOwnProperty）取，空字段名与 "__proto__" 一样是普通字段；
715	// - 数组按下标取（"0" 或非零开头的十进制整数，且在长度范围内；"-" 越界不命中）；
716	// - 字段缺失、下标越界或需要在标量/null 上继续遍历时，返回 undefined 表示
717	//   “无法取到值”。调用方据此判定不命中——缺失与显式 null 必须区分。
718	function resolvePointer(root: unknown, segments: readonly string[]): unknown {
719	  let current: unknown = root;
720	  for (const segment of segments) {
721	    if (Array.isArray(current)) {
722	      if (!/^(0|[1-9]\d*)$/.test(segment)) {
723	        return undefined;
724	      }
725	      const index = Number(segment);
726	      if (index >= current.length) {
727	        return undefined;
728	      }
729	      current = current[index];
730	    } else if (isPlainObject(current)) {
731	      if (!Object.prototype.hasOwnProperty.call(current, segment)) {
732	        return undefined;
733	      }
734	      current = current[segment];
735	    } else {
736	      // 在 null / 字符串 / 数字 / 布尔上无法继续遍历
737	      return undefined;
738	    }
739	  }
740	  return current;
741	}
742	
743	// 等值匹配：严格相等、不做类型转换；=== 下数字 0 与 -0 本就相等。
744	// 取不到值（undefined）永不等于任何条件值，故显式 null 条件不会命中缺失字段。
745	function conditionMatches(root: unknown, condition: BranchCondition): boolean {
746	  const actual = resolvePointer(root, condition.segments);
747	  return actual !== undefined && actual === condition.value;
748	}
749	
750	// 一支的全部条件都满足才命中
751	function branchMatches(branch: LiveBranch, parsedBody: unknown): boolean {
752	  for (const condition of branch.conditions) {
753	    if (!conditionMatches(parsedBody, condition)) {
754	      return false;
755	    }
756	  }
757	  return true;
758	}
759	
760	// 根据正文值选择分支（首支命中）并从该支或兜底序列预留下一项
761	function reserveForBody(endpoint: LiveEndpoint, parsedBody: unknown): ReservedResponse {
762	  for (const branch of endpoint.branches) {
763	    if (branchMatches(branch, parsedBody)) {
764	      const { position, item } = reserveFromSequence(branch.responses, branch);
765	      return { position, item, branchId: branch.id, sequence: branch.responses };
766	    }
767	  }
768	  const { position, item } = reserveFromSequence(endpoint.responses, endpoint);
769	  return { position, item, branchId: null, sequence: endpoint.responses };
770	}
