834	// 已清空记录的投递回调落到空集合上：不取消响应，旧请求之后完成也不得重新出现。
835	class RequestLog {
836	  private records: RequestRecord[] = [];
837	  // 仍可能被投递事件更新的记录 id 集合（清空后旧 id 不在其中）
838	  private readonly live = new Map<number, RequestRecord>();
839	  private nextId = 1;
840	
841	  create(entry: {
842	    method: string;
843	    target: string;
844	    path: string;
845	    rawHeaders: readonly string[];
846	    body: Buffer;
847	    configVersion: number;
848	  }): RequestRecord {
849	    const id = this.nextId;
850	    this.nextId += 1;
851	    const record: RequestRecord = {
852	      id,
853	      receivedAt: new Date().toISOString(),
854	      request: {
855	        method: entry.method,
856	        target: entry.target,
857	        path: entry.path,
858	        rawHeaders: entry.rawHeaders,
859	        bodyBytes: entry.body.byteLength,
860	        body: encodeBodyLosslessly(entry.body),
861	      },
862	      configVersion: entry.configVersion,
863	      matched: false,
864	      endpoint: null,
865	      bodyValidationPassed: null,
866	      bodyRejection: null,
867	      branchSelection: null,
868	      sequencePosition: null,
869	      sequenceLength: null,
870	      plannedResponse: null,
871	      delivery: 'pending',
872	    };
873	    this.records.push(record);
874	    this.live.set(id, record);
875	    return record;
876	  }
877	
878	  // 写出完成；对已清空（不再存活）的记录是 no-op
879	  markDelivered(id: number, status: DeliveryStatus): void {
880	    const record = this.live.get(id);
881	    if (!record) {
882	      return;
883	    }
884	    // 一旦完成写出即为终态：之后的连接正常关闭不得回退为 interrupted
885	    if (record.delivery === 'sent') {
886	      return;
887	    }
888	    record.delivery = status;
889	  }
890	
891	  // 调用时一致快照：拷贝当前存活记录，不推进任何序列
892	  snapshot(): readonly RequestRecord[] {
893	    return [...this.records];
894	  }
895	
896	  // 清空一次移除当时全部记录（含待发送项）；不取消响应、不改配置/版本/序列。
897	  // 清空前已完整接收的请求随后完成或失败都不再出现。
898	  clear(): number {
899	    const removed = this.records.length;
900	    this.records = [];
901	    this.live.clear();
902	    return removed;
903	  }
904	}
905	
906	// 原始正文字节的无损文本表示：先尝试严格 UTF-8；失败则用 base64 承载任意字节。
907	// 记录的是原始字节而非解析后的 JSON，避免任何信息损失。
908	// ignoreBOM：开头 BOM（EF BB BF）必须保留在文本中（默认行为会将其丢弃），
909	// 否则文本重新编码回不去原始字节，快照就不再无损。
910	function encodeBodyLosslessly(body: Buffer): { encoding: 'utf-8' | 'base64'; content: string } {
911	  try {
912	    const text = new TextDecoder('utf-8', { fatal: true, ignoreBOM: true }).decode(body);
913	    return { encoding: 'utf-8', content: text };
914	  } catch {
915	    return { encoding: 'base64', content: body.toString('base64') };
916	  }
917	}
