1151	// ---------------------------------------------------------------------------
1152	// 文件读取与（重新）加载：读、解析、校验全部通过后才一次性替换
1153	// ---------------------------------------------------------------------------
1154	
1155	function describeError(e: unknown): string {
1156	  return e instanceof Error ? e.message : String(e);
1157	}
1158	
1159	// 读取 -> 解析 -> 严格校验；任何一步失败都抛出含文件路径与可定位原因的错误
1160	async function loadSpecsFromFile(configPath: string): Promise<EndpointSpec[]> {
1161	  let text: string;
1162	  try {
1163	    text = await readFile(configPath, 'utf8');
1164	  } catch (e) {
1165	    throw new Error(`读取配置文件 ${configPath} 失败：${describeError(e)}`);
1166	  }
1167	
1168	  let raw: unknown;
1169	  try {
1170	    raw = JSON.parse(text);
1171	  } catch (e) {
1172	    throw new Error(`配置文件 ${configPath} 不是合法 JSON：${describeError(e)}`);
1173	  }
1174	
1175	  try {
1176	    return validateConfig(raw);
1177	  } catch (e) {
1178	    throw new Error(`配置文件 ${configPath} 校验失败：${describeError(e)}`);
1179	  }
1180	}
1181	
1182	async function loadStateFromFile(configPath: string, version: number): Promise<LiveState> {
1183	  return buildState(version, await loadSpecsFromFile(configPath));
1184	}
