1186	// ---------------------------------------------------------------------------
1187	// 离线兼容报告（compare 子命令）
1188	// ---------------------------------------------------------------------------
1189	//
1190	// 兼容方向固定为 旧 -> 新：旧配置能按“方法 + 字面路径”匹配且通过正文检查的
1191	// 每一种请求，在新配置中仍须匹配并通过。只比较接口存在性与请求接受条件；
1192	// 响应状态/头/正文/延迟与序列差异不影响结论。
1193	//
1194	// 双方都配置 requestBody 时，比较的是“规则所接受 JSON 值的集合包含关系”
1195	// L(旧规则) ⊆ L(新规则)，而不是文本比较或抽样请求；每个不兼容点都附一份
1196	// 具体反例（旧规则接受、新规则拒绝的完整 JSON 值）。
1197	
1198	interface ReportReason {
1199	  // 正文差异：RFC 6901 指针（根为 ""）；接口级原因（如接口删除）无此字段
1200	  readonly pointer?: string;
1201	  readonly message: string;
1202	}
1203	
1204	interface ReportExample {
1205	  readonly method: HttpMethod;
1206	  readonly path: string;
1207	  readonly headers: { readonly [name: string]: string };
1208	  readonly body: string;
1209	}
1210	
1211	interface EndpointReport {
1212	  readonly method: HttpMethod;
1213	  readonly path: string;
1214	  readonly compatible: boolean;
1215	  readonly reasons: readonly ReportReason[];
1216	  readonly example?: ReportExample;
1217	}
1218	
1219	interface CompareReport {
1220	  readonly compatible: boolean;
1221	  readonly oldFile: string;
1222	  readonly newFile: string;
1223	  readonly endpoints: readonly EndpointReport[];
1224	}
1225	
1226	interface BodyViolation {
1227	  readonly pointer: string;
1228	  readonly message: string;
1229	  // 完整请求正文反例：被旧规则接受、被新规则拒绝
1230	  readonly value: unknown;
1231	}
1232	
1233	// 生成被规则接受的最小 JSON 值：object 只含必填字段，array 取空数组；
1234	// 枚举节点任选一候选（优先非 null 项——“类型收紧”反例需要非 null 样本）。
1235	// 字段名可能是 "" 或 "__proto__"，一律用无原型对象按自有字段构造。
1236	function sampleValue(rule: BodyRule): unknown {
1237	  if (rule.kind !== 'object' && rule.kind !== 'array' && rule.enum !== undefined) {
1238	    const nonNull = rule.enum.find((v) => v !== null);
1239	    return nonNull === undefined ? null : nonNull;
1240	  }
1241	  switch (rule.kind) {
1242	    case 'string':
1243	      return 'contractlab';
1244	    case 'number':
1245	    case 'integer':
1246	      return 0;
1247	    case 'boolean':
1248	      return false;
1249	    case 'null':
1250	      return null;
1251	    case 'array':
1252	      return [];
1253	    case 'object': {
1254	      const obj: Record<string, unknown> = Object.create(null);
1255	      for (const [name, field] of rule.fields) {
1256	        if (field.required) {
1257	          obj[name] = sampleValue(field.rule);
1258	        }
1259	      }
1260	      return obj;
1261	    }
1262	  }
1263	}
1264	
1265	// 规则是否接受 null：type:null 或 nullable:true；有枚举时 null 还须列入候选
1266	// （可空不越过枚举）。object / array 节点没有枚举。
1267	function ruleAcceptsNullValue(rule: BodyRule): boolean {
1268	  if (!rule.nullable && rule.kind !== 'null') {
1269	    return false;
1270	  }
1271	  if (rule.kind === 'object' || rule.kind === 'array') {
1272	    return true;
1273	  }
1274	  return rule.enum === undefined || rule.enum.includes(null);
1275	}
1276	
1277	// 规则的非 null 接受集合是否非空：枚举仅含 null 项的标量规则只接受 null
1278	function hasNonNullAcceptedValues(rule: BodyRule): boolean {
1279	  if (rule.kind === 'null') {
1280	    return false;
1281	  }
1282	  if (rule.kind === 'object' || rule.kind === 'array') {
1283	    return true;
1284	  }
1285	  return rule.enum === undefined || rule.enum.some((v) => v !== null);
1286	}
1287	
1288	// 在 object 规则的最小样本上补一个字段（字段值本身须被该字段规则接受）
1289	function sampleObjectWith(
1290	  rule: Extract<BodyRule, { kind: 'object' }>,
1291	  name: string,
1292	  value: unknown,
1293	): Record<string, unknown> {
1294	  const obj = sampleValue(rule) as Record<string, unknown>;
1295	  obj[name] = value;
1296	  return obj;
1297	}
1298	
1299	// 生成被规则拒绝的 JSON 值（顶层类型即不符；任何规则都存在这样的值）
1300	function violateValue(rule: BodyRule): unknown {
1301	  switch (rule.kind) {
1302	    case 'number':
1303	      return 'contractlab'; // 非数字
1304	    case 'integer':
1305	      return 0.5; // 非整数
1306	    default:
1307	      return 0; // 非 string / boolean / null / object / array
1308	  }
1309	}
1310	
1311	function kindLabel(rule: BodyRule): string {
1312	  if (rule.kind === 'object') {
1313	    return rule.additionalProperties ? 'object（允许未声明字段）' : 'object（拒绝未声明字段）';
1314	  }
1315	  return rule.kind;
1316	}
1317	
1318	// 选一个两个规则都未声明的字段名，用于构造“额外字段”反例
1319	function freshFieldName(
1320	  oldFields: ReadonlyMap<string, FieldRule>,
1321	  newFields: ReadonlyMap<string, FieldRule>,
1322	): string {
1323	  for (let i = 0; ; i += 1) {
1324	    const name = i === 0 ? 'extra' : `extra_${i}`;
1325	    if (!oldFields.has(name) && !newFields.has(name)) {
1326	      return name;
1327	    }
1328	  }
1329	}
