1331	// 非 null 值是否被标量规则接受：先过类型约束，再过枚举候选（如有）
1332	function scalarValueAccepted(
1333	  rule: Extract<BodyRule, { kind: ScalarKind }>,
1334	  value: unknown,
1335	): boolean {
1336	  switch (rule.kind) {
1337	    case 'string':
1338	      if (typeof value !== 'string') {
1339	        return false;
1340	      }
1341	      break;
1342	    case 'boolean':
1343	      if (typeof value !== 'boolean') {
1344	        return false;
1345	      }
1346	      break;
1347	    case 'number':
1348	      if (typeof value !== 'number' || !Number.isFinite(value)) {
1349	        return false;
1350	      }
1351	      break;
1352	    case 'integer':
1353	      if (!Number.isInteger(value)) {
1354	        return false;
1355	      }
1356	      break;
1357	    case 'null':
1358	      return false; // 本函数只处理非 null 值
1359	  }
1360	  return rule.enum === undefined || rule.enum.includes(value as EnumValue);
1361	}
1362	
1363	// 标量规则的简述（用于原因消息）：类型 + 枚举候选（如有）
1364	function scalarRuleLabel(rule: Extract<BodyRule, { kind: ScalarKind }>): string {
1365	  return rule.enum === undefined ? rule.kind : `${rule.kind}（${enumExpectedText(rule.enum)}）`;
1366	}
1367	
1368	// 生成一个属于指定类型、但不在给定枚举中的值（类型取值无限，必然找得到）
1369	function freshValueOutsideEnum(
1370	  kind: 'string' | 'number' | 'integer',
1371	  enumValues: readonly EnumValue[],
1372	): string | number {
1373	  if (kind === 'string') {
1374	    for (let i = 0; ; i += 1) {
1375	      const candidate = i === 0 ? 'contractlab' : `contractlab_${i}`;
1376	      if (!enumValues.includes(candidate)) {
1377	        return candidate;
1378	      }
1379	    }
1380	  }
1381	  for (let i = 0; ; i += 1) {
1382	    if (!enumValues.includes(i)) {
1383	      return i;
1384	    }
1385	  }
1386	}
