1404	      }
1405	      if (!scalarValueAccepted(newRule, value)) {
1406	        out.push({
1407	          pointer,
1408	          value,
1409	          message: `枚举收紧：旧规则接受的枚举值 ${JSON.stringify(value)} 不被新规则（${scalarRuleLabel(newRule)}）接受`,
1410	        });
1411	      }
1412	    }
1413	    return;
1414	  }
1415	
1416	  if (newRule.enum !== undefined) {
1417	    // 旧规则接受整个类型集合，新规则只接受枚举候选
1418	    if (oldRule.kind === 'boolean') {
1419	      for (const value of [false, true]) {
1420	        if (!scalarValueAccepted(newRule, value)) {
1421	          out.push({
1422	            pointer,
1423	            value,
