1563	        });
1564	      }
1565	      continue;
1566	    }
1567	    const sub: BodyViolation[] = [];
1568	    collectViolations(oldField.rule, newField.rule, childPointer, sub);
1569	    for (const s of sub) {
1570	      out.push({
1571	        pointer: s.pointer,
1572	        message: s.message,
1573	        value: sampleObjectWith(oldRule, name, s.value),
