4482	  // 合并两支的固定取值；同名字段常量不同（严格相等）则不存在共同正文
4483	  private mergePins(
4484	    a: ReadonlyMap<string, BranchConditionValue>,
4485	    b: ReadonlyMap<string, BranchConditionValue>,
4486	  ): Map<string, BranchConditionValue> | null {
4487	    const merged = new Map(a);
4488	    for (const [name, value] of b) {
4489	      const existing = merged.get(name);
4490	      if (existing !== undefined && existing !== value) {
4491	        return null;
4492	      }
4493	      merged.set(name, value);
4494	    }
4495	    return merged;
4496	  }
