4581	// 选择诊断目标接口并执行范围预检；任何不满足都抛 ReachError（退出 2）
4582	function selectReachEndpoint(
4583	  specs: readonly EndpointSpec[],
4584	  configFile: string,
4585	  routePath: string,
4586	): { endpoint: EndpointSpec; index: number } {
4587	  const postMatches = specs
4588	    .map((endpoint, index) => ({ endpoint, index }))
4589	    .filter((entry) => entry.endpoint.method === 'POST' && entry.endpoint.path === routePath);
4590	
4591	  if (postMatches.length === 0) {
4592	    const existing = specs.filter((ep) => ep.method === 'POST').map((ep) => `POST ${ep.path}`);
4593	    throw new ReachError(
4594	      `场景文件 ${configFile} 中不存在 POST 接口 ${JSON.stringify(routePath)}。` +
4595	        (existing.length > 0 ? `现有的 POST 接口：${existing.join('，')}` : '该配置没有 POST 接口'),
4596	    );
4597	  }
4598	
4599	  const { endpoint, index } = postMatches[0];
4600	  const where = `endpoints[${index}]`;
4601	  if (endpoint.branches.length === 0) {
4602	    throw new ReachError(
4603	      `${where}（POST ${routePath}）未声明 branches：reach 仅诊断声明了响应分支的接口`,
4604	    );
4605	  }
4606	  if (!endpoint.bodyRule || endpoint.bodyRule.kind !== 'object') {
4607	    throw new ReachError(
4608	      `${where}.requestBody ${endpoint.bodyRule ? `的类型为 "${endpoint.bodyRule.kind}"` : ''}：` +
4609	        'reach 仅支持根 requestBody 为 object（可附 nullable）的分支接口',
4610	    );
4611	  }
4612	
4613	  // when 指针范围预检：单段、指向根对象已声明的标量字段（其他字段仍按递归规则处理）
4614	  const rootFields = endpoint.bodyRule.fields;
4615	  for (let b = 0; b < endpoint.branches.length; b += 1) {
4616	    const branch = endpoint.branches[b];
4617	    for (const condition of branch.conditions) {
4618	      const condWhere = `${where}.branches[${b}].when[${JSON.stringify(condition.pointer)}]`;
4619	      if (condition.segments.length !== 1) {
4620	        throw new ReachError(
4621	          `${condWhere} 指针 ${JSON.stringify(condition.pointer)} 含 ${condition.segments.length} 段：` +
4622	            'reach 仅支持单段 RFC 6901 指针（指向根对象的已声明标量字段），根指针与深层指针超出诊断范围',
4623	        );
4624	      }
4625	      const name = condition.segments[0];
4626	      const field = rootFields.get(name);
4627	      if (!field) {
4628	        throw new ReachError(
4629	          `${condWhere} 指向根对象未声明字段 ${JSON.stringify(name)}：` +
4630	            'reach 仅诊断指向已声明字段的条件（未声明字段仍按 additionalProperties 等现有规则处理）',
4631	        );
4632	      }
4633	      if (field.rule.kind === 'object' || field.rule.kind === 'array') {
4634	        throw new ReachError(
4635	          `${condWhere} 指向字段 ${JSON.stringify(name)}，其规则类型为 "${field.rule.kind}"：` +
4636	            'reach 仅支持指向标量字段的条件，对象/数组字段超出诊断范围',
4637	        );
4638	      }
4639	    }
4640	  }
4641	
4642	  return { endpoint, index };
4643	}
