        else if (t === 'integer') f.enum = [0, 1, 2].filter(() => coin(0.6));
        else f.enum = [true, false].filter(() => coin(0.7));
        if (f.enum.length === 0) delete f.enum;
      }
      if (coin(0.3)) f.nullable = true;
