  // 标量：该叶被条件引用的全部常量 + null + 一个合法代表 + 少量异类型值
  const ptr = '/' + segs.join('/');
  for (const v of refsByPtr.get(ptr) ?? []) add(v);
  add(null);
  add(legalRep(rule));
  add('a'); add(0); add(true);
  return vals;
}
function resolve(root, seg) {
  let cur = root;
  for (const s of seg) {
    if (cur === null || typeof cur !== 'object' || !Object.prototype.hasOwnProperty.call(cur, s)) return undefined;
    cur = cur[s];
  }
  return cur;
}
function decode(p) { return p.slice(1).split('/').map((s) => s.replace(/~1/g, '/').replace(/~0/g, '~')); }

const ITER = 150;
let failures = 0;
const dir = await mkdtemp(path.join(tmpdir(), 'reach-fuzz-'));
try {
  for (let it = 0; it < ITER; it += 1) {
    seed = 123456789 + it * 1013;
    const schema = genSchema(2);
    if (coin(0.2)) schema.nullable = true;
    const ls = leaves(schema, [], []);
    if (ls.length === 0) { it -= 1; continue; }
    const nb = 1 + Math.floor(rnd() * 3);
    const branches = [];
    const usedPtrs = new Set();
    for (let i = 0; i < nb; i += 1) {
      const nc = 1 + Math.floor(rnd() * 2);
      const when = {};
      for (let j = 0; j < nc; j += 1) {
        const leaf = pick(ls);
        when[leaf.pointer] = condValue(leaf.rule);
        usedPtrs.add(leaf.pointer);
      }
      branches.push({ id: `br${i}`, when, responses: [{ status: 200, headers: {}, body: `B${i}`, delay: 0 }] });
    }
    const cfg = { endpoints: [{ method: 'POST', path: '/p', requestBody: schema, responses: [{ status: 200, headers: {}, body: 'FB', delay: 0 }], branches }] };
    const file = path.join(dir, 'c.json');
    await writeFile(file, JSON.stringify(cfg));
    const refsByPtr = new Map();
    for (const br of branches) for (const [p, v] of Object.entries(br.when)) {
      if (!refsByPtr.has(p)) refsByPtr.set(p, []);
      if (!refsByPtr.get(p).some((x) => x === v)) refsByPtr.get(p).push(v);
    }
    const cli = await runCli(['reach', '--config', file, '--path', '/p']);
    if (cli.code !== 0 && cli.code !== 1) { console.log('UNEXPECTED EXIT', it, cli.code, cli.err); failures += 1; continue; }
    const rep = JSON.parse(cli.out);

    // brute force
    const accepted = genValues(schema, 0, refsByPtr, []).filter((v) => v !== undefined && accepts(schema, v));
    const cseg = branches.map((br) => Object.entries(br.when).map(([p, value]) => ({ s: decode(p), value })));
    const sat = (body, i) => cseg[i].every((c) => { const a = resolve(body, c.s); return a !== undefined && a === c.value; });
    const first = (body) => { for (let i = 0; i < branches.length; i += 1) if (sat(body, i)) return i; return null; };
    for (let i = 0; i < branches.length; i += 1) {
      let exp;
      if (!accepted.some((b) => sat(b, i))) exp = 'contradictory';
      else if (accepted.some((b) => first(b) === i)) exp = 'reachable';
      else exp = 'covered';
      if (rep.branches[i].status !== exp) {
        console.log('MISMATCH it', it, 'branch', i, 'exp', exp, 'got', rep.branches[i].status, JSON.stringify(cfg));
        failures += 1;
      }
      if (exp === 'covered') {
        const by = [];
        for (let j = 0; j < i; j += 1) if (accepted.some((b) => sat(b, i) && first(b) === j)) by.push(branches[j].id);
        if (JSON.stringify(rep.branches[i].coveredBy) !== JSON.stringify(by)) {
          console.log('COVEREDBY it', it, 'branch', i, 'exp', by, 'got', rep.branches[i].coveredBy);
          failures += 1;
        }
      }
    }
    const fbExp = accepted.some((b) => first(b) === null);
    if ((rep.fallback.status === 'reachable') !== fbExp) {
      console.log('FALLBACK it', it, 'exp', fbExp, 'got', rep.fallback.status, JSON.stringify(cfg));
      failures += 1;
    }
  }
} finally {
  await rm(dir, { recursive: true, force: true });
}
console.log(failures === 0 ? `ALL ${ITER} FUZZ CASES MATCH` : `${failures} FAILURES`);
process.exit(failures === 0 ? 0 : 1);

