// Randomized differential: reach CLI vs exact brute-force over accepted bodies.
import { spawn } from 'node:child_process';
import { mkdtemp, writeFile, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { pathToFileURL } from 'node:url';
const { accepts } = await import(pathToFileURL('/Users/Shared/products-20261005/contractlab/b/task016/test/helpers.ts').href);

const APP = '/Users/Shared/products-20261005/contractlab/b/task016/app.ts';

function runCli(args) {
  return new Promise((resolve) => {
    const c = spawn(process.execPath, [APP, ...args]);
    let out = '', err = '';
    c.stdout.setEncoding('utf8').on('data', (d) => (out += d));
    c.stderr.setEncoding('utf8').on('data', (d) => (err += d));
    c.on('exit', (code) => resolve({ code, out, err }));
  });
}

