  return seed / 0x7fffffff;
}
function pick(arr) { return arr[Math.floor(rnd() * arr.length)]; }
function coin(p) { return rnd() < p; }

function genSchema(depth) {
  const fields = {};
  const n = 1 + Math.floor(rnd() * 2); // 最多 2 个字段，控制穷举规模
  for (let i = 0; i < n; i += 1) {
    const name = pick(['s', 'n', 'b', 'x', 'y']) + i;
    if (depth > 0 && coin(0.4)) {
      fields[name] = genSchema(depth - 1);
      fields[name].type = 'object';
    } else {
      const t = pick(['string', 'integer', 'boolean']);
      const f = { type: t };
      if (coin(0.6)) {
        if (t === 'string') f.enum = ['a', 'b', 'c'].filter(() => coin(0.6));
        else if (t === 'integer') f.enum = [0, 1, 2].filter(() => coin(0.6));
        else f.enum = [true, false].filter(() => coin(0.7));
        if (f.enum.length === 0) delete f.enum;
      }
      if (coin(0.3)) f.nullable = true;
      fields[name] = f;
    }
    if (coin(0.5)) fields[name].required = true;
  }
  return { type: 'object', fields, additionalProperties: false };
}

// collect in-scope scalar leaves with pointers and rules
function leaves(schema, segs, acc) {
  for (const [name, f] of Object.entries(schema.fields)) {
    const p = [...segs, name];
    if (f.type === 'object') leaves(f, p, acc);
    else acc.push({ pointer: '/' + p.join('/'), rule: f });
  }
  return acc;
}

function condValue(rule) {
  const r = rnd();
  if (r < 0.7) {
    // legal
    if (rule.enum && rule.enum.length) return pick(rule.enum);
    if (rule.type === 'string') return pick(['a', 'b', 'c']);
    if (rule.type === 'integer') return pick([0, 1, 2]);
    return pick([true, false]);
  }
  if (r < 0.82) {
    if (rule.type === 'string') return pick([0, true, null]);
    if (rule.type === 'integer') return pick(['a', 0.5, null]);
    return pick(['x', 0, null]);
  }
  if (r < 0.9 && rule.enum && rule.enum.length) {
    const pool = rule.type === 'string' ? ['a', 'b', 'c'] : rule.type === 'integer' ? [0, 1, 2] : [true, false];
    return pick(pool.filter((v) => !rule.enum.includes(v)));
  }
  return null;
}

// universe generation: per-leaf tailored values (referenced constants + null +
// one legal representative + a few illegal values), object missing/null/present.
function legalRep(rule) {
  if (rule.enum && rule.enum.length) {
    return rule.enum.find((v) => v !== null) ?? null;
  }
  if (rule.type === 'string') return 'a';
  if (rule.type === 'integer') return 0;
  return false;
}
function genValues(rule, depth, refsByPtr, segs) {
  const vals = [];
  const add = (v) => { if (!vals.some((x) => x === v)) vals.push(v); };
  if (depth < 6 && rule.type === 'object') {
    add(undefined); // 缺失（必填对象在 accepts 过滤时被排除）
    if (rule.nullable === true) add(null);
    let objs = [{}];
    for (const [name, fr] of Object.entries(rule.fields)) {
      const choices = genValues(fr, depth + 1, refsByPtr, [...segs, name]);
      const next = [];
      for (const o of objs) for (const v of choices) {
        const m = { ...o };
        if (v !== undefined) m[name] = v;
        next.push(m);
      }
      objs = next;
    }
    for (const o of objs) add(o);
    return vals;
  }
  // 标量“接受宇宙”的精确代表（非法值会被 accepts 过滤、无需纳入）：
  // 缺失（可选时合格）+ 被引用且合格的常量 + 显式 null（若接受）+ 一个其余合格值。
  const ptr = '/' + segs.join('/');
  const referenced = refsByPtr.get(ptr) ?? [];
  const scalarAccepts = (v) => accepts({ type: rule.type, enum: rule.enum, nullable: rule.nullable }, v);
  add(undefined);
  for (const v of referenced) if (scalarAccepts(v)) add(v);
  if (scalarAccepts(null)) add(null);
  if (rule.enum) {
    for (const v of rule.enum) if (v !== null && !referenced.some((r) => r === v)) { add(v); break; }
  } else if (rule.type === 'boolean') {
    add(false); add(true);
  } else if (rule.type === 'string') {
    add(referenced.some((r) => r === 'a') ? 'contractlab-other' : 'a');
  } else {
    add(referenced.some((r) => r === 0) ? 77 : 0);
  }
  return vals;
}
function resolve(root, seg) {
  let cur = root;
  for (const s of seg) {
    if (cur === null || typeof cur !== 'object' || !Object.prototype.hasOwnProperty.call(cur, s)) return undefined;
    cur = cur[s];
  }
  return cur;
}
function decode(p) { return p.slice(1).split('/').map((s) => s.replace(/~1/g, '/').replace(/~0/g, '~')); }

const ITER = 150;
let failures = 0;
const dir = await mkdtemp(path.join(tmpdir(), 'reach-fuzz-'));
try {
  for (let it = 0; it < ITER; it += 1) {
    seed = 123456789 + it * 1013;
    const schema = genSchema(2);
    if (coin(0.2)) schema.nullable = true;
    const ls = leaves(schema, [], []);
    if (ls.length === 0) { it -= 1; continue; }
    const nb = 1 + Math.floor(rnd() * 3);
    const branches = [];
    for (let i = 0; i < nb; i += 1) {
      const nc = 1 + Math.floor(rnd() * 2);
      const when = {};
      const chosen = new Set();
      for (let j = 0; j < nc; j += 1) {
        // 同一分支内选不同叶，避免 JSON 键折叠成空 when
        let leaf;
        let guard = 0;
        do { leaf = pick(ls); guard += 1; } while (chosen.has(leaf.pointer) && guard < 20);
        if (chosen.has(leaf.pointer)) continue;
        chosen.add(leaf.pointer);
        when[leaf.pointer] = condValue(leaf.rule);
      }
      branches.push({ id: `br${i}`, when, responses: [{ status: 200, headers: {}, body: `B${i}`, delay: 0 }] });
    }
    const cfg = { endpoints: [{ method: 'POST', path: '/p', requestBody: schema, responses: [{ status: 200, headers: {}, body: 'FB', delay: 0 }], branches }] };
    const file = path.join(dir, 'c.json');
    await writeFile(file, JSON.stringify(cfg));
    const refsByPtr = new Map();
    for (const br of branches) for (const [p, v] of Object.entries(br.when)) {
      if (!refsByPtr.has(p)) refsByPtr.set(p, []);
      if (!refsByPtr.get(p).some((x) => x === v)) refsByPtr.get(p).push(v);
    }
    const cli = await runCli(['reach', '--config', file, '--path', '/p']);
    if (cli.code !== 0 && cli.code !== 1) { console.log('UNEXPECTED EXIT', it, cli.code, cli.err); failures += 1; continue; }
    const rep = JSON.parse(cli.out);

    // brute force
    const accepted = genValues(schema, 0, refsByPtr, []).filter((v) => v !== undefined && accepts(schema, v));
    const cseg = branches.map((br) => Object.entries(br.when).map(([p, value]) => ({ s: decode(p), value })));
    const sat = (body, i) => cseg[i].every((c) => { const a = resolve(body, c.s); return a !== undefined && a === c.value; });
    const first = (body) => { for (let i = 0; i < branches.length; i += 1) if (sat(body, i)) return i; return null; };
    for (let i = 0; i < branches.length; i += 1) {
      let exp;
      if (!accepted.some((b) => sat(b, i))) exp = 'contradictory';
      else if (accepted.some((b) => first(b) === i)) exp = 'reachable';
      else exp = 'covered';
      if (rep.branches[i].status !== exp) {
        console.log('MISMATCH it', it, 'branch', i, 'exp', exp, 'got', rep.branches[i].status, JSON.stringify(cfg));
        failures += 1;
      }
      if (exp === 'covered') {
        const by = [];
        for (let j = 0; j < i; j += 1) if (accepted.some((b) => sat(b, i) && first(b) === j)) by.push(branches[j].id);
        if (JSON.stringify(rep.branches[i].coveredBy) !== JSON.stringify(by)) {
          console.log('COVEREDBY it', it, 'branch', i, 'exp', by, 'got', rep.branches[i].coveredBy);
          failures += 1;
        }
      }
    }
    const fbExp = accepted.some((b) => first(b) === null);
    if ((rep.fallback.status === 'reachable') !== fbExp) {
      console.log('FALLBACK it', it, 'exp', fbExp, 'got', rep.fallback.status, JSON.stringify(cfg));
      failures += 1;
    }
  }
} finally {
  await rm(dir, { recursive: true, force: true });
}
console.log(failures === 0 ? `ALL ${ITER} FUZZ CASES MATCH` : `${failures} FAILURES`);
process.exit(failures === 0 ? 0 : 1);

